/**
 * Who a farm task belongs to.
 *
 * `farm_tasks.assignee_ids` (one or more people) is the explicit choice
 * Micheal makes on the task form — `assigned_to` is the older single-person
 * column, still honoured when the array is empty. With nobody picked, the
 * answer depends on where the task came from:
 *   - automated tasks (generated by the nightly cron, or confirmed from a
 *     chef email) are the farm owner's to do;
 *   - a hand-written task with nobody picked is for anyone on the team.
 * Resolving this at read time keeps the generators untouched.
 *
 * Pure — tested in tests/lib/tasks/assign.test.ts.
 */

export const ANYONE_LABEL = "Anyone";

export interface AssignableTask {
  assigned_to: string | null;
  assignee_ids?: string[] | null;
  source: string;
}

export function isAutomatedSource(source: string): boolean {
  return source !== "manual";
}

/**
 * Microgreen work (the cron's sow / move / harvest tray tasks, or any task
 * linked to a microgreen crop or batch) is the farm owner's alone: farm
 * hands never see it, can't finish it, and it can't be assigned to them
 * (Micheal 2026-11-21).
 */
export function isMicrogreenTask(task: {
  source: string;
  microgreen_crop_id?: string | null;
  microgreen_batch_id?: string | null;
}): boolean {
  return task.source === "microgreens-auto" || !!task.microgreen_crop_id || !!task.microgreen_batch_id;
}

/** Everyone the task belongs to; an empty list means it is for anyone. */
export function effectiveAssigneeIds(task: AssignableTask, ownerId: string | null): string[] {
  const explicit = (task.assignee_ids ?? []).filter(Boolean);
  if (explicit.length > 0) return Array.from(new Set(explicit));
  if (task.assigned_to) return [task.assigned_to];
  return isAutomatedSource(task.source) && ownerId ? [ownerId] : [];
}

/** Is this task on `personId`'s list — theirs, or open to anyone? */
export function isForPerson(assigneeIds: string[], personId: string): boolean {
  return assigneeIds.length === 0 || assigneeIds.includes(personId);
}

/** First name is enough on a phone-width chip ("Micheal Breedlove" → "Micheal"). */
export function shortPersonName(fullName: string | null | undefined): string | null {
  const first = fullName?.trim().split(/\s+/)[0];
  return first || null;
}

export interface WorkloadRow {
  /** null = tasks for anyone. */
  id: string | null;
  name: string;
  todo: number;
  upcoming: number;
}

/**
 * "Who has what": open tasks per person — due now vs coming up. People
 * first (busiest first), the shared "Anyone" pile last.
 */
type WorkloadTask = { assignee_ids: string[]; assignee_names: string[] };

export function summarizeWorkload(todo: WorkloadTask[], upcoming: WorkloadTask[]): WorkloadRow[] {
  const rows = new Map<string, WorkloadRow>();
  // A task shared by two people counts once for each of them.
  const bump = (t: WorkloadTask, key: "todo" | "upcoming") => {
    const people =
      t.assignee_ids.length > 0
        ? t.assignee_ids.map((id, i) => ({ id, name: t.assignee_names[i] ?? ANYONE_LABEL }))
        : [{ id: null as string | null, name: ANYONE_LABEL }];
    for (const p of people) {
      const k = p.id ?? "";
      const row = rows.get(k) ?? { id: p.id, name: p.name, todo: 0, upcoming: 0 };
      row[key] += 1;
      rows.set(k, row);
    }
  };
  todo.forEach((t) => bump(t, "todo"));
  upcoming.forEach((t) => bump(t, "upcoming"));
  return Array.from(rows.values()).sort((a, b) => {
    if ((a.id === null) !== (b.id === null)) return a.id === null ? 1 : -1;
    return b.todo + b.upcoming - (a.todo + a.upcoming) || a.name.localeCompare(b.name);
  });
}
